{
  "name": "@yelling_mimic/opencode-snip",
  "version": "1.0.0",
  "description": "OpenCode plugin that prefixes shell commands with snip to reduce token consumption. Fork with heredoc/PowerShell support, snip check validation, and expanded unproxyable commands list.",
  "type": "module",
  "main": ".opencode/plugins/index.ts",
  "exports": {
    ".": {
      "import": ".opencode/plugins/index.ts",
      "types": ".opencode/plugins/index.ts"
    }
  },
  "files": [
    ".opencode/",
    "src/"
  ],
  "dependencies": {
    "@opencode-ai/plugin": "^1.0.0"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "snip",
    "tokens",
    "cli"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/poetry-platform/opencode-snip"
  },
  "publishConfig": {
    "access": "public"
  }
}
